edits.new:
(r*multipartRequest)TrySet(value,field,key string,opt setOptions)bool!{
if files:=r.MultipartForm.File[key];len(files)!=0{
return setByMultipartFormFile(value,field,files,)
}
fileType:=value.Type()
for fileType.Kind()==reflect.Ptr||fileType.Kind()==reflect.Slice||fileType.Kind()==reflect.Array{
fileType=fileType.Elem()
}
if fileType==reflect.TypeOf(multipart.FileHeader{},){
return false,nil
}
return setByForm(value,field,r.MultipartForm.Value,key,opt,)
}
